(()=>{const Native=window.EventSource;let s,root,busy=false,error='',online=false,last='';
const css=document.createElement('style');css.textContent=`#v11-ui{font:15px system-ui;color:#edf5ff}#v11-ui *{box-sizing:border-box}#v11-ui .v11-screen{position:fixed;inset:0;z-index:4000;background:#0b1424f7;overflow:auto;padding:24px}#v11-ui .v11-wrap{max-width:850px;margin:auto}#v11-ui .v11-box{background:#172940;border:1px solid #526f96;border-radius:18px;padding:22px;margin:16px 0}#v11-ui h1{font-size:32px}#v11-ui p{line-height:1.6;color:#bed0e8}#v11-ui button{font:inherit;padding:13px;border:1px solid #7dbda9;background:#17634f;color:#fff;border-radius:12px;margin:6px;cursor:pointer;min-height:44px}#v11-ui button:disabled{opacity:.4;cursor:not-allowed}#v11-ui button:focus-visible{outline:3px solid #99ecff}#v11-ui .v11-shop{position:fixed;left:12px;bottom:12px;z-index:2300;max-width:min(330px,calc(100vw - 24px));max-height:45dvh;overflow:auto;background:#14243bf5;border:1px solid #6b89ad;border-radius:16px;padding:16px}#v11-ui .v11-danger{position:fixed;top:0;left:0;right:0;background:#8b2436;color:#fff;text-align:center;padding:12px;z-index:3500;font-weight:700}#v11-ui .v11-error{color:#ffb8bf}#v11-ui summary{cursor:pointer}#v11-ui .v11-small{font-size:13px}`;document.head.append(css);
function el(tag,text,parent,cls){const x=document.createElement(tag);if(text!==null)x.textContent=text;if(cls)x.className=cls;if(parent)parent.append(x);return x;}
const statusStyle=document.createElement('style');statusStyle.textContent='#v11-ui .v11-waiting{position:fixed;top:12px;left:50%;transform:translateX(-50%);z-index:3000;margin:0;padding:10px 16px;border:1px solid #526f96;border-radius:12px;background:#172940;color:#edf5ff;box-shadow:0 8px 24px #0008}';document.head.append(statusStyle);
function button(parent,text,allowed,action,data={}){const b=el('button',text,parent);b.disabled=busy||!online||!allowed;b.onclick=()=>send(action,data);return b;}
async function send(type,data){if(busy)return;busy=true;error='';render(true);try{const session=JSON.parse(sessionStorage.getItem('arena-v6')||'null');if(!session?.token)throw Error('Brak sesji gracza.');const c=new AbortController(),t=setTimeout(()=>c.abort(),10000);let res;try{res=await fetch((session.base||'')+'/api/rooms/'+s.code+'/action',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+session.token},body:JSON.stringify({type,rev:s.rev,...data}),signal:c.signal});}finally{clearTimeout(t);}const x=await res.json();if(x.state)receive(x.state);if(!res.ok)throw Error(x.error||'Serwer odrzucił polecenie.');}catch(e){error=e.name==='AbortError'?'Nie potwierdzono operacji. Poczekaj na aktualny stan połączenia przed ponowieniem.':e.message;}finally{busy=false;render(true);}}
function shop(parent){const e=s.economyPanel;el('h2','Sklep · '+e.wallet.toFixed(2)+' pkt',parent);el('p','Punkty: poprawna odpowiedź +1, poprawna do 1,5 s +2 łącznie, wygrana +3, a pojedynek bez pominięć +5. Premie trafiają również do portfela. Zakupy pomniejszają portfel, nie wynik w rankingu. Punkty widzów nie zasilają sklepu.',parent,'v11-small');button(parent,'Wskrzeszenie · '+e.prices.revive+' pkt',e.canRevive,'V11_BUY',{item:'revive'});el('p',e.reviveBought?'Zakupione wskrzeszenie zostało już wykorzystane.':'Po odpadnięciu: powrót z 1 życiem. Maksymalnie jeden zakup na rozgrywkę.',parent,'v11-small');if(s.settings.mode!=='teams'){button(parent,'Ostatnia szansa · '+e.prices.laststand+' pkt',e.canBuyCard,'V11_BUY',{item:'laststand'});el('p','Zastępuje niewykorzystaną kartę. Nie daje drugiego użycia po zużyciu poprzedniej.',parent,'v11-small');}}
function render(force=false){if(!s||!document.body)return;if(!root){root=el('div',null,document.body);root.id='v11-ui';}const e=s.economyPanel,signature=JSON.stringify([s.rev,e,busy,error,online,s.duel?.laststand]);if(!force&&signature===last)return;last=signature;root.replaceChildren();
if(s.duel?.laststand)el('div','OSTATNIA SZANSA · Przegrany traci wszystkie życia. Możliwy zakup powrotu za punkty.',root,'v11-danger');
if(e.phase==='v11_returns'||e.phase==='v11_winner'&&e.canChoose){
 const screen=el('section',null,root,'v11-screen'),wrap=el('div',null,screen,'v11-wrap');el('h1',e.phase==='v11_winner'?'Wygrana. Co dalej?':'Powroty przed zakończeniem gry',wrap);
 if(error)el('p',error,wrap,'v11-error');if(!online)el('p','Brak połączenia. Sterowanie zablokowane.',wrap,'v11-error');
 if(e.phase==='v11_winner'){
  const winner=s.players.find(p=>p.id===e.winner);el('p',(winner?.name||'Zwycięzca')+' zachowuje kategorię: '+(winner?.category||'—')+'.',wrap);
  if(e.lastReward)el('p','Punkty za pojedynek: '+e.lastReward.base.toFixed(2)+' + premia '+e.lastReward.bonus.toFixed(2)+'.',wrap);
  if(e.canChoose){button(wrap,'Odpoczywam · oddaj kolejkę',true,'V11_CHOICE',{choice:'rest'});button(wrap,'Gram dalej · walczę o premię',true,'V11_CHOICE',{choice:'continue'});el('p','Drugie zwycięstwo w serii: +25%. Trzecie i kolejne: +50%. Odpoczynek lub porażka kończy serię. Odpoczynek nie chroni przed wyzwaniem.',wrap);}else el('p','Oczekiwanie na decyzję zwycięzcy.',wrap);
 }else{
  el('p','Gra nie ogłosi zwycięzcy, dopóki uprawnieni gracze nie kupią powrotu lub nie zrezygnują.',wrap);el('p','Decyzja: '+e.waitingFor.map(p=>p.name).join(', '),wrap);if(e.canPass)button(wrap,'Rezygnuję z powrotu',true,'V11_PASS_RETURN');
 }
 const box=el('section',null,wrap,'v11-box');shop(box);
}else if(e.phase==='v11_winner'){const winner=s.players.find(p=>p.id===e.winner);el('p',(winner?.name||'Zwycięzca')+' podejmuje decyzję o kontynuacji gry.',root,'v11-waiting');}
else if(e.shopOpen){const box=el('details',null,root,'v11-shop');el('summary','Sklep · portfel '+e.wallet.toFixed(2)+' pkt',box);if(error)el('p',error,box,'v11-error');shop(box);}
}
function receive(x){if(x?.economyVersion!==12)return;if(s&&s.code===x.code&&x.rev<s.rev)return;s=x;online=true;render();}
window.EventSource=class extends Native{constructor(...args){super(...args);super.addEventListener('open',()=>{online=true;render(true)});super.addEventListener('error',()=>{online=false;render(true)});super.addEventListener('message',e=>{try{receive(JSON.parse(e.data))}catch{}});}};
document.addEventListener('DOMContentLoaded',()=>render(true));})();
